/* Generated by tools/gen_g3507_pin_routes.py from TI mspm0g350x.h.
 * iomux is the zero-based PINCM index; role is peripheral-specific. */
typedef struct {
    uint8_t iomux;
    uint8_t pf;
    uint8_t instance;
    uint8_t role;
} g3507_route_t;

enum { G3507_I2C_SCL = 0, G3507_I2C_SDA = 1 };
enum { G3507_SPI_SCLK = 0, G3507_SPI_PICO = 1, G3507_SPI_POCI = 2,
       G3507_SPI_CS0 = 3, G3507_SPI_CS1_POCI1 = 4,
       G3507_SPI_CS2_POCI2 = 5, G3507_SPI_CS3_POCI3 = 6 };
